import sys
try:
    import pypdf
except ImportError:
    print('no pypdf'); sys.exit()
import glob
for f in glob.glob('*.pdf'):
    try:
        r=pypdf.PdfReader(f); t=' '.join((p.extract_text() or '') for p in r.pages)
        print('=====',f,len(t)); print(t[:2500].encode('ascii','replace').decode())
    except Exception as e: print(f,e)
"

